func TestFTSRetainedVMRejectsUnapprovedDifferences(t *testing.T) {
	for _, slot := range []stmt.FTSRetainedSlot{stmt.SearchOwnPrefixInsertV1, stmt.SearchOwnPrefixDeleteV1, stmt.SearchFragmentPrefixDelete} {
		spec, _ := slot.Specification()
		identity := `"main"."` + spec.Table + `":fts5`
		before, input := retainedVMFixture(slot), retainedVMFixture(slot)
		update, begin := 7, 10
		if slot == stmt.SearchOwnPrefixDeleteV1 {
			update, begin = 8, 11
		}
		mapped, err := mapFTSRetainedVM(input, slot, identity)
		if err != nil {
			t.Fatal(slot, err)
		}
		if !reflect.DeepEqual(input, before) {
			t.Fatal("raw evidence mutated")
		}
		before.Values[update][5], before.Values[begin][5] = identity, identity
		if !reflect.DeepEqual(mapped, before) {
			t.Fatal("unapproved operand changed")
		}
		for name, change := range map[string]func(*Rows){"pair": func(r *Rows) { r.Values[begin][5] = "vtab:BADBAD" }, "third_vtab": func(r *Rows) { r.Values[1][5] = "vtab:123ABCD" }, "other_operand": func(r *Rows) { r.Values[update][6] = int64(3) }} {
			t.Run(string(slot)+"/"+name, func(t *testing.T) {
				bad := retainedVMFixture(slot)
				change(&bad)
				if _, err := mapFTSRetainedVM(bad, slot, identity); err == nil {
					t.Fatal("unapproved native difference erased")
				}
			})
		}
	}
	if _, err := mapFTSRetainedVM(retainedVMFixture(stmt.SearchOwnPrefixInsertV1), "unknown", `"main"."search_own_prefix":fts5`); err == nil {
		t.Fatal("unknown slot mapped")
	}
	if _, err := mapFTSRetainedVM(retainedVMFixture(stmt.SearchOwnPrefixInsertV1), stmt.SearchOwnPrefixInsertV1, `"main"."unknown":fts5`); err == nil {
		t.Fatal("unknown vtab mapped")
	}
}
